// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    DEP_BANK c;

    function setUp() public {
        c = new DEP_BANK();
    }

    function testFuzz_property(uint256 depositAmount, uint256 collectAmount) public {
        vm.assume(depositAmount <= VALUE_CAP);
        LogFile log = new LogFile();
        c.SetLogFile(address(log));

        depositAmount = bound(depositAmount, 1, type(uint128).max);
        collectAmount = bound(collectAmount, 1, depositAmount);

        address actor = address(0xabcd);
        vm.deal(actor, depositAmount);

        vm.prank(actor);
        c.Deposit{value: depositAmount}();

        vm.prank(actor);
        c.Collect(collectAmount);

        uint256 postBalance = c.balances(actor);
        bool invariantHolds = postBalance + collectAmount <= depositAmount + collectAmount;
        assertTrue(invariantHolds, "caller balance after Collect must not exceed pre-call deposit plus amount");
    }
}
